import re

def get_sn1_months_detailed(filepath):
    """Extract Savings Notes monthly data with year tracking"""
    with open(filepath, 'r') as f:
        content = f.read()

    start = content.find('Table SN-1')
    if start < 0:
        return []

    end = content.find('Table', start + 100)
    if end < 0:
        end = content.find('Source:', start)
    if end < 0:
        end = len(content)

    section = content[start:end]
    months_start = section.find('Months:')
    if months_start < 0:
        return []

    months_section = section[months_start:months_start+3000]
    lines = months_section.split('\n')

    results = []
    current_year = None

    month_map = {'Jan': 1, 'Feb': 2, 'Mar': 3, 'Apr': 4, 'May': 5, 'June': 6, 
                 'Jul': 7, 'Aug': 8, 'Sept': 9, 'Sep': 9, 'Oct': 10, 'Nov': 11, 'Dec': 12}

    for line in lines:
        if 'Months:' in line or 'nan' in line:
            continue

        # Parse row
        parts = [p.strip() for p in line.split('|') if p.strip()]
        if len(parts) >= 8:
            period = parts[0]
            redemp = parts[4]

            if redemp.isdigit():
                # Extract year
                year_match = re.search(r'(\d{4})-', period)
                if year_match:
                    current_year = year_match.group(1)
                    month_name = re.search(r'-(\w{3})', period)
                    if month_name:
                        month = month_name.group(1)
                        month_num = month_map.get(month, 0)
                        if month_num > 0:
                            results.append((f"{current_year}-{month:3s}", int(redemp)))
                else:
                    # Check for month name at start
                    month_match = re.match(r'^(\w{3})\.?', period)
                    if month_match and current_year:
                        month = month_match.group(1)
                        month_key = month_map.get(month, 0)
                        if month_key > 0:
                            results.append((f"{current_year}-{month:3s}", int(redemp)))

    return results

# Let's verify all key months for each window
# For Nov 1973 to Oct 1974 - take from the last bulletin that contains each month

# Window 1: Nov 1973 - Oct 1974
# Best source: 1974_12 (contains Nov 1973 through Nov 1974)
